from reportlab.lib import colors
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import inch
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak

OUT = "references/google-adk/evidence/google-adk-federation-scale-brief.pdf"
s = getSampleStyleSheet()
s.add(ParagraphStyle(name="TitleBlue", parent=s["Title"], fontSize=24, leading=28, textColor=colors.HexColor("#102a43"), spaceAfter=12))
s.add(ParagraphStyle(name="H2Blue", parent=s["Heading2"], fontSize=15, leading=18, textColor=colors.HexColor("#0b7285"), spaceBefore=10, spaceAfter=6))
s.add(ParagraphStyle(name="BodySmall", parent=s["BodyText"], fontSize=9.5, leading=13, spaceAfter=6))
s.add(ParagraphStyle(name="MonoSmall", parent=s["BodyText"], fontName="Courier", fontSize=8.2, leading=11, backColor=colors.HexColor("#f1f5f9"), borderPadding=6, spaceAfter=8))
P = lambda text, style="BodySmall": Paragraph(text, s[style])

def footer(canvas, doc):
    canvas.saveState(); canvas.setFont("Helvetica", 8); canvas.setFillColor(colors.HexColor("#64748b"))
    canvas.drawString(.65*inch, .42*inch, "Ratify Protocol | Independent Google ADK reference")
    canvas.drawRightString(7.85*inch, .42*inch, str(doc.page)); canvas.restoreState()

def table(rows, widths, header):
    t = Table(rows, colWidths=widths)
    t.setStyle(TableStyle([("BACKGROUND", (0,0), (-1,0), colors.HexColor(header)), ("TEXTCOLOR", (0,0), (-1,0), colors.white), ("FONTNAME", (0,0), (-1,0), "Helvetica-Bold"), ("FONTSIZE", (0,0), (-1,-1), 8.5), ("LEADING", (0,0), (-1,-1), 11), ("GRID", (0,0), (-1,-1), .35, colors.HexColor("#cbd5e1")), ("VALIGN", (0,0), (-1,-1), "TOP"), ("ROWBACKGROUNDS", (0,1), (-1,-1), [colors.white, colors.HexColor("#f8fafc")]), ("LEFTPADDING", (0,0), (-1,-1), 6), ("RIGHTPADDING", (0,0), (-1,-1), 6), ("TOPPADDING", (0,0), (-1,-1), 5), ("BOTTOMPADDING", (0,0), (-1,-1), 5)]))
    return t

story = [P("Ratify + Google ADK", "TitleBlue"), P("Cross-domain multi-agent authorization at scale", "H2Blue"), P("This independent executable reference answers how delegated authority can cross trust domains, survive multi-agent handoffs, and remain enforceable as protected calls grow from 10 to 1,000,000. It is not a Google partnership, endorsement, or production capacity claim."), P("The decision boundary", "H2Blue"), P("ADK selects and routes a tool call. Workload identity authenticates the caller. The receiving service reconstructs the exact consequential operation and verifies Ratify evidence immediately before the protected action. The model never handles keys or proof bytes."), P("Trust Domain A  →  ADK coordinator  →  ADK broker  →  Trust Domain B worker  →  independent receiver  →  protected action", "MonoSmall"), P("Two roots, one receiver decision", "H2Blue"), P("The receiver pins an authority root for the delegated mandate and a separate workload-admission root for the receiving domain. Both chains must recognize the same worker key. A widened region or node ceiling is denied before the protected handler runs."), table([["Scenario", "Result", "Action"], ["Valid worker + admission", "allow", "1 invocation"], ["Broker widens ceiling", "constraint_denied", "0 invocations"], ["Foreign admission root", "admission_binding_failed", "0 invocations"], ["Revoked or replayed proof", "deny", "0 invocations"]], [3.1*inch, 2.1*inch, 1.3*inch], "#102a43"), PageBreak(), P("What changes at scale", "TitleBlue"), P("Every measured call receives a unique challenge, signs the operation, verifies both chains, evaluates constraints and revocation, consumes the challenge, and records the protected action."), table([["Tier", "Recorded result"], ["10 / 100 / 1,000", "Measured exact-call workload"], ["1,000,000", "900,000 allows; 100,000 constraint denials; 900,000 protected actions"], ["Throughput", "369.693 receiver decisions/sec with 8 workers"], ["Encoded proof", "56,244 bytes, dual-root hybrid presentation"]], [2.0*inch, 4.5*inch], "#0b7285"), Spacer(1, 10), P("The scale sample deliberately uses constraint denials only. Replay, revocation, malformed-admission, and untrusted-root cases are covered by the deterministic gate, not mixed into the throughput sample."), P("Production shape", "H2Blue"), P("The local reference uses one process. A production deployment distributes trust bundles and signed revocation snapshots, runs stateless verifier workers regionally, and uses a shared atomic challenge store so a single-use challenge cannot be accepted twice. Ratify Verify is not required synchronously on every call."), P("Measured versus not deployed", "H2Blue"), P("Measured: public ADK callback path, Streamable HTTP MCP, dual-root federation, multi-agent routing, receiver-side enforcement, revocation, replay resistance, and the exact-call local benchmark. Not deployed here: Vertex AI Agent Engine, Google Agent Identity, A2A transport, TLS workload authentication, multi-host storage, external revocation distribution, or real Google Cloud provisioning."), PageBreak(), P("Run, inspect, reproduce", "TitleBlue"), P("The reference runs without a Gemini API key or Google Cloud project."), P("Deterministic gate", "H2Blue"), P("./scripts/google-adk-reference-check.sh", "MonoSmall"), P("Latest recorded run: 49 tests passed, zero skipped, failed, or xfailed."), P("Scale harness", "H2Blue"), P("python -m authority_reference.scale_benchmark --calls 10,100,1000,1000000 --workers 8 --output evidence/federation-scale-local-rerun.json", "MonoSmall"), P("Canonical links", "H2Blue"), P("Source: github.com/identities-ai/ratify-protocol/tree/main/references/google-adk<br/>Architecture and scale note: references/google-adk/FEDERATION_SCALE.md<br/>Evidence: references/google-adk/evidence/reference-evidence.md and federation-scale-local.json<br/>Visual walkthrough: labs.ratifyprotocol.com/google-adk"), P("Positioning for platform teams", "H2Blue"), P("ADK, IAM, Agent Identity, A2A, and Agent Engine can continue to do what they already do. Ratify adds a portable, receiver-enforced proof that a recognized principal authorized this exact action under these constraints.")]
SimpleDocTemplate(OUT, pagesize=letter, rightMargin=.65*inch, leftMargin=.65*inch, topMargin=.6*inch, bottomMargin=.65*inch).build(story, onFirstPage=footer, onLaterPages=footer)
print(OUT)
